sql.where:
lea.deleted_yn = 'N'

    and lea.achievement_id::text ilike concat('%', #{criteria.normalizedManagementNo}, '%')


    and coalesce(kps.name, u.login_id) ilike concat('%', #{criteria.normalizedTeacherName}, '%')


    and lea.management_item_code = #{criteria.normalizedManagementItemCode}


    and lea.occurred_date >= #{criteria.occurredDateFrom}


    and lea.occurred_date <= #{criteria.occurredDateTo}


    and lea.certification_status = #{criteria.normalizedCertificationStatus}




            and lea.target_user_id = #{requesterUserId}


            and (
                lea.target_user_id = #{requesterUserId}
                or exists (
                    select 1
                    from evaluation_organization_mappings eom
                    where eom.user_id = #{requesterUserId}
                      and eom.business_type = 'FACULTY_ACHIEVEMENT'
                      and eom.data_scope in ('BUSINESS', 'ALL')
                )
            )

mapper.select:
select count(*)
from evaluation_finalizations ef
where ef.target_user_id = #{targetUserId}
  and ef.evaluation_year = #{evaluationYear}
  and ef.final_status = 'EVALUATION_CONFIRMED'
